/**
 * Cloudflare configuration. Generated by `cf migrate` from the wrangler
 * config it replaced; the comments below are ours.
 *
 * The bundler-specific half — the `#env` alias and the assets directory —
 * lives in `wrangler.config.ts`, because this Worker is not a Vite project and
 * `cf` bundles it through wrangler.
 */

import { bindings, defineConfig, triggers } from "cf/config";

export default defineConfig({
  worker: {
    name: "id-kbn-one",
    compatibilityDate: "2026-10-19",

    // Written by `scripts/cf-build.sh`: `deno bundle` produces it, because
    // the source resolves JSR specifiers and workspace import maps that
    // esbuild knows nothing about. That bundle leaves `#env` unresolved on
    // purpose, for the alias in `wrangler.config.ts` to supply.
    entrypoint: "main/worker/worker.js",

    observability: {
      enabled: true,
    },

    // D1 has no TTL of its own. Reads already treat an expired row as absent,
    // so this only reclaims storage and a missed run costs nothing but space.
    triggers: [
      triggers.scheduled({
        schedule: "23 4 * * *",
      }),
    ],

    env: {
      // Public configuration, not secrets: the signing key lives in D1. These
      // did not come across from Deno Deploy, where they were only ever set in
      // the dashboard.
      //
      // Do not change `RP_ID`. A WebAuthn credential is bound to the RP ID it
      // was created under, so a different value here makes every existing
      // passkey unusable, and putting it back does not bring them back — the
      // authenticator keeps the original binding. This value is the one
      // production used, confirmed by the repository owner.
      RP_ID: bindings.text("id.kbn.one"),
      RP_NAME: bindings.text("kbn.one ID"),
      IDP_ORIGIN: bindings.text("https://id.kbn.one"),
      // Hostnames, subdomains included. `kbn.one` is what production must have
      // allowed: a live /authorize carried
      // redirect_uri=https://ga-cen.kbn.one/… The old Deno Deploy host is
      // deliberately not carried over.
      AUTHORIZE_WHITELIST: bindings.text("kbn.one"),
      PUSH_CONTACT: bindings.text("mailto:o@kbn.one"),

      // Deno KV's replacement, already holding the migrated data. D1 rather
      // than Workers KV because the app needs compare-and-set: single-use
      // OAuth codes, refresh-token reuse detection, DPoP replay rejection and
      // push rate limiting all rest on it, and Workers KV would keep returning
      // success while those guarantees quietly vanished.
      DB: bindings.d1({
        name: "id-kbn-one",
        id: "1ad1c197-5119-4392-bf55-e863fe70334e",
      }),
    },
  },
});
